// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface RecallIn {
  drug_id: number;
  /** The recalled batches of the medicine */
  batch_ids?: number[] | null;
  /** Recall every batch of the medicine */
  all_batches?: boolean;
  source: "DRAP" | "Manufacturer" | "Supplier" | "Internal";
  /** The DRAP alert or the supplier's letter */
  reference?: string | null;
  /** ClassI: serious harm possible (contact every patient); ClassII: temporary harm; ClassIII: unlikely harm */
  recall_class: "ClassI" | "ClassII" | "ClassIII";
  reason: string;
  /** The recall reaches patients: list and contact everyone who received it */
  contact_patients: boolean;
}

