/** Open a batch recall — POST /api/v1/drug-recalls (who may call: holders of pharmacy.recall.manage). */
export function openRecall(body: RecallIn): Promise<RecallDetailOut> {
  return api<RecallDetailOut>("POST", `/drug-recalls`, body, { idempotent: true });
}

/** The recall register — GET /api/v1/drug-recalls (who may call: holders of pharmacy.recall.view). */
export function listRecalls(query?: { status?: "Open" | "Closed" | "Cancelled" | null; drug_id?: number | null }): Promise<RecallOut[]> {
  return api<RecallOut[]>("GET", withQuery(`/drug-recalls`, query), undefined);
}

/** A recall and where its batches went — GET /api/v1/drug-recalls/{recall_id} (who may call: holders of pharmacy.recall.view). */
export function getRecall(recall_id: number): Promise<RecallDetailOut> {
  return api<RecallDetailOut>("GET", `/drug-recalls/${recall_id}`, undefined);
}

/** Remove the recalled stock left — POST /api/v1/drug-recalls/{recall_id}/remove-stock (who may call: holders of pharmacy.recall.manage). */
export function removeRecalledStock(recall_id: number, body: RecallNoteIn): Promise<RecallDetailOut> {
  return api<RecallDetailOut>("POST", `/drug-recalls/${recall_id}/remove-stock`, body, { idempotent: true });
}

/** Record a contact with a patient of a recall — PATCH /api/v1/drug-recalls/{recall_id}/patients/{recall_patient_id} (who may call: holders of pharmacy.recall.manage). */
export function recordContact(recall_id: number, recall_patient_id: number, body: RecallContactIn): Promise<RecallDetailOut> {
  return api<RecallDetailOut>("PATCH", `/drug-recalls/${recall_id}/patients/${recall_patient_id}`, body);
}

/** Close a recall — POST /api/v1/drug-recalls/{recall_id}/close (who may call: holders of pharmacy.recall.manage). */
export function closeRecall(recall_id: number, body: RecallNoteIn): Promise<RecallDetailOut> {
  return api<RecallDetailOut>("POST", `/drug-recalls/${recall_id}/close`, body, { idempotent: true });
}

/** Cancel a recall opened by mistake — POST /api/v1/drug-recalls/{recall_id}/cancel (who may call: holders of pharmacy.recall.manage). */
export function cancelRecall(recall_id: number, body: MedicationReasonIn): Promise<RecallDetailOut> {
  return api<RecallDetailOut>("POST", `/drug-recalls/${recall_id}/cancel`, body, { idempotent: true });
}

/** Drug stock with batches in FEFO order — GET /api/v1/drugs/{drug_id}/stock-status (who may call: holders of pharmacy.formulary.view or pharmacy.stock.view). */
export function stockStatus(drug_id: number): Promise<DrugStockDetailOut> {
  return api<DrugStockDetailOut>("GET", `/drugs/${drug_id}/stock-status`, undefined);
}
